'use client';

import { ReactNode, createContext, useState } from 'react';
import type { StepperProps } from './types';

interface StepperContextValue extends StepperProps {
  clickable?: boolean;
  isError?: boolean;
  isLoading?: boolean;
  isVertical?: boolean;
  stepCount?: number;
  expandVerticalSteps?: boolean;
  activeStep: number;
  initialStep: number;
}

type StepperContextProviderProps = {
  value: Omit<StepperContextValue, 'activeStep'> & { activeStep?: number };
  children: ReactNode;
};

const StepperContext = createContext<
  StepperContextValue & {
    nextStep: () => void;
    prevStep: () => void;
    resetSteps: () => void;
    setStep: (step: number) => void;
  }
>({
  steps: [],
  activeStep: 0,
  initialStep: 0,
  nextStep: () => {},
  prevStep: () => {},
  resetSteps: () => {},
  setStep: () => {},
});

const StepperProvider = ({ value, children }: StepperContextProviderProps) => {
  const isError = value.state === 'error';
  const isLoading = value.state === 'loading';

  const [innerStep, setInnerStep] = useState(value.initialStep);
  const controlled = value.activeStep !== undefined;
  const activeStep = controlled ? (value.activeStep as number) : innerStep;

  const setStep = (step: number) => {
    if (!controlled) setInnerStep(step);
    value.onStepChange?.(step);
  };

  const nextStep = () => setStep(activeStep + 1);

  const prevStep = () => setStep(activeStep - 1);

  const resetSteps = () => setStep(value.initialStep);

  return (
    <StepperContext.Provider
      value={{
        ...value,
        isError,
        isLoading,
        activeStep,
        nextStep,
        prevStep,
        resetSteps,
        setStep,
      }}
    >
      {children}
    </StepperContext.Provider>
  );
};

export { StepperContext, StepperProvider };

'use client';

import { forwardRef } from 'react';
import { cn } from '@/lib/utils';
import { StepButtonContainer } from './step-button-container';
import { StepIcon } from './step-icon';
import { StepLabel } from './step-label';
import type { StepSharedProps } from './types';
import { useStepper } from './use-stepper';

const HorizontalStep = forwardRef<HTMLDivElement, StepSharedProps>((props, ref) => {
  const {
    isError,
    isLoading,
    onClickStep,
    variant,
    clickable,
    checkIcon: checkIconContext,
    errorIcon: errorIconContext,
    styles,
    steps,
    setStep,
  } = useStepper();

  const {
    index,
    isCompletedStep,
    isCurrentStep,
    hasVisited,
    icon,
    label,
    description,
    isKeepError,
    state,
    checkIcon: checkIconProp,
    errorIcon: errorIconProp,
  } = props;

  const localIsLoading = isLoading || state === 'loading';
  const localIsError = isError || state === 'error';


  const active = variant === 'line' ? isCompletedStep || isCurrentStep : isCompletedStep;

  const checkIcon = checkIconProp || checkIconContext;
  const errorIcon = errorIconProp || errorIconContext;

  return (
    <div
      aria-disabled={!hasVisited}
      className={cn(
        'stepper__horizontal-step',
        'flex items-center relative transition-all duration-200',
        '[&:not(:last-child)]:flex-1',
        '[&:not(:last-child)]:after:transition-all [&:not(:last-child)]:after:duration-200',
        "[&:not(:last-child)]:after:content-[''] [&:not(:last-child)]:after:h-[2px] [&:not(:last-child)]:after:bg-button-border-outline-default",
        'data-[completed=true]:[&:not(:last-child)]:after:bg-primary',
        'data-[invalid=true]:[&:not(:last-child)]:after:bg-destructive',
        variant === 'circle-alt' &&
          'justify-start flex-col flex-1 [&:not(:last-child)]:after:relative [&:not(:last-child)]:after:order-[-1] [&:not(:last-child)]:after:start-[50%] [&:not(:last-child)]:after:end-[50%] [&:not(:last-child)]:after:top-[calc(var(--step-icon-size)/2)] [&:not(:last-child)]:after:w-[calc((100%-var(--step-icon-size))-(var(--step-gap)))]',
        variant === 'circle' &&
          '[&:not(:last-child)]:after:flex-1 [&:not(:last-child)]:after:ms-[var(--step-gap)] [&:not(:last-child)]:after:me-[var(--step-gap)]',
        variant === 'line' && 'flex-col flex-1 border-t-[3px] border-solid data-[active=true]:border-primary',
        styles?.['horizontal-step'],
      )}
      data-optional={steps[index || 0]?.optional}
      data-completed={isCompletedStep}
      data-active={active}
      data-invalid={localIsError}
      data-clickable={clickable}
      onClick={() => onClickStep?.(index || 0, setStep)}
      ref={ref}
    >
      <div
        className={cn(
          'stepper__horizontal-step-container',
          'flex items-center',
          variant === 'circle-alt' && 'flex-col justify-center gap-1',
          variant === 'line' && 'w-full',
          styles?.['horizontal-step-container'],
        )}
      >
        <StepButtonContainer {...{ ...props, isError: localIsError, isLoading: localIsLoading }}>
          <StepIcon
            {...{
              index,
              isCompletedStep,
              isCurrentStep,
              isError: localIsError,
              isKeepError,
              isLoading: localIsLoading,
            }}
            icon={icon}
            checkIcon={checkIcon}
            errorIcon={errorIcon}
          />
        </StepButtonContainer>
        <StepLabel label={label} description={description} {...{ isCurrentStep, hasVisited }} />
      </div>
    </div>
  );
});

export { HorizontalStep };

'use client';

import { CSSProperties, Children, ReactElement, ReactNode, Ref, cloneElement, forwardRef, isValidElement } from 'react';
import { cn } from '@/lib/utils';
import { usePreset } from '@/components/ui/labels-context';
import { StepperProvider } from './context';
import { Step } from './step';
import type { StepItem, StepProps, StepperProps } from './types';
import { useMediaQuery } from './use-media-query';
import { useStepper } from './use-stepper';

const VARIABLE_SIZES = {
  sm: '36px',
  md: '40px',
  lg: '44px',
};

const Stepper = forwardRef<HTMLDivElement, StepperProps>((props, ref: Ref<HTMLDivElement>) => {
  const {
    className,
    children,
    orientation: orientationProp,
    state,
    responsive,
    checkIcon,
    errorIcon,
    onClickStep,
    mobileBreakpoint,
    expandVerticalSteps = false,
    initialStep = 0,
    size,
    theme,
    iconSize,
    steps,
    variant,
    styles,
    variables,
    scrollTracking = false,
    activeStep: activeStepProp,
    onStepChange,
    ...rest
  } = props;

  const zero = usePreset() === 'zero';
  const childArr = Children.toArray(children);

  const items = [] as ReactElement[];

  const footer = childArr.map((child, _index) => {
    if (!isValidElement(child)) {
      throw new Error('Stepper children must be valid React elements.');
    }
    if (child.type === Step) {
      items.push(child);
      return null;
    }

    return child;
  });

  const stepCount = items.length;

  const isMobile = useMediaQuery(`(max-width: ${mobileBreakpoint || '768px'})`);

  const clickable = !!onClickStep;

  const orientation = isMobile && responsive ? 'vertical' : orientationProp;

  const isVertical = orientation === 'vertical';

  return (
    <StepperProvider
      value={{
        initialStep,
        activeStep: activeStepProp,
        onStepChange,
        orientation,
        state,
        size,
        theme,
        iconSize,
        responsive,
        checkIcon,
        errorIcon,
        onClickStep,
        clickable,
        stepCount,
        isVertical,
        variant: variant || 'circle',
        expandVerticalSteps,
        steps,
        scrollTracking,
        styles,
      }}
    >
      <div
        ref={ref}
        className={cn(
          'stepper__main-container',
          'flex w-full flex-wrap',
          stepCount === 1 ? 'justify-end' : 'justify-between',
          orientation === 'vertical' ? 'flex-col' : 'flex-row',
          variant === 'line' && orientation === 'horizontal' && 'gap-4',
          className,
          styles?.['main-container'],
        )}
        style={
          {
            '--step-icon-size': variables?.['--step-icon-size'] || (zero ? 'var(--size-stepper-marker)' : `${VARIABLE_SIZES[size || 'md']}`),
            '--step-gap': variables?.['--step-gap'] || '8px',
          } as CSSProperties
        }
        {...rest}
      >
        <VerticalContent>{items}</VerticalContent>
      </div>
      {orientation === 'horizontal' && <HorizontalContent>{items}</HorizontalContent>}
      {footer}
    </StepperProvider>
  );
});

Stepper.defaultProps = {
  size: 'md',
  orientation: 'horizontal',
  responsive: true,
};

const VerticalContent = ({ children }: { children: ReactNode }) => {
  const { activeStep } = useStepper();

  const childArr = Children.toArray(children);
  const stepCount = childArr.length;

  return (
    <>
      {Children.map(children, (child, i) => {
        const isCompletedStep = (isValidElement(child) && (child.props as any).isCompletedStep) ?? i < activeStep;
        const isLastStep = i === stepCount - 1;
        const isCurrentStep = i === activeStep;

        const stepProps = {
          index: i,
          isCompletedStep,
          isCurrentStep,
          isLastStep,
        };

        if (isValidElement(child)) {
          return cloneElement(child, stepProps);
        }
        return null;
      })}
    </>
  );
};

const HorizontalContent = ({ children }: { children: ReactNode }) => {
  const { activeStep } = useStepper();
  const childArr = Children.toArray(children);

  if (activeStep > childArr.length) {
    return null;
  }

  return (
    <>
      {Children.map(childArr[activeStep], (node) => {
        if (!isValidElement(node)) {
          return null;
        }
        return Children.map(node.props.children, (childNode) => childNode);
      })}
    </>
  );
};

export { Step, Stepper, useStepper };
export type { StepItem, StepProps, StepperProps };

'use client';

import { ReactNode } from 'react';
import { Button } from '@/components/ui/button';
import { useLabels, usePreset } from '@/components/ui/labels-context';
import { cn } from '@/lib/utils';
import type { StepSharedProps } from './types';
import { useStepper } from './use-stepper';

type StepButtonContainerProps = StepSharedProps & {
  children?: ReactNode;
};

const themeClasses = {
  light:
    'border-transparent bg-transparent data-[active=true]:border-transparent data-[active=true]:bg-transparent data-[active=true]:text-primary data-[current=true]:border-transparent data-[current=true]:bg-transparent data-[current=true]:text-primary',
  mid: 'bg-transparent data-[active=true]:bg-transparent data-[active=true]:text-primary data-[current=true]:bg-transparent data-[current=true]:text-primary',
  dark: 'data-[current=true]:bg-primary data-[current=true]:text-primary-foreground',
} as const;

const StepButtonContainer = ({
  isCurrentStep,
  isCompletedStep,
  children,
  isError,
  isLoading: isLoadingProp,
  onClickStep,
  label,
  index,
}: StepButtonContainerProps) => {
  const { clickable, isLoading: isLoadingContext, variant, styles, theme } = useStepper();
  const l = useLabels();
  const zero = usePreset() === 'zero';

  const currentStepClickable = clickable || !!onClickStep;

  const isLoading = isLoadingProp || isLoadingContext;

  if (variant === 'line') {
    return null;
  }

  // Accessible name: "Step 2: Account, completed". The status words follow the same rules as the visual marker.
  const status = isError && (isCurrentStep || isCompletedStep) ? l.stepFailed : isCompletedStep ? l.stepCompleted : isCurrentStep ? l.stepCurrent : undefined;
  const stepName = l.stepName((index ?? 0) + 1, typeof label === 'string' ? label : undefined);
  const accessibleName = status ? `${stepName}, ${status}` : stepName;

  return (
    <Button
      variant="ghost"
      type="button"
      tabIndex={currentStepClickable ? 0 : -1}
      className={cn(
        'stepper__step-button-container',
        'pointer-events-none rounded-full p-0',
        'h-[var(--step-icon-size)] w-[var(--step-icon-size)]',
        'flex items-center justify-center rounded-full border-2 border-solid',
        'data-[clickable=true]:pointer-events-auto',
        'data-[active=true]:text-white data-[active=true]:border-primary data-[active=true]:bg-primary',
        'data-[current=true]:bg-secondary data-[current=true]:border-primary',
        'data-[invalid=true]:bg-destructive data-[invalid=true]:border-destructive data-[invalid=true]:text-destructive-foreground',
        // Zero: the marker is the 22px circle with a soft brand halo on the current step.
        zero && 'data-[current=true]:ring-halo data-[current=true]:ring-ring/ring-halo',
        theme && themeClasses[theme],
        styles?.['step-button-container'],
      )}
      data-theme={theme}
      aria-label={accessibleName}
      aria-current={isCurrentStep ? 'step' : undefined}
      data-current={isCurrentStep}
      data-invalid={isError && (isCurrentStep || isCompletedStep)}
      data-active={isCompletedStep}
      data-clickable={currentStepClickable}
      data-loading={isLoading && (isCurrentStep || isCompletedStep)}
    >
      {children}
    </Button>
  );
};

export { StepButtonContainer };

'use client';

import { cva } from 'class-variance-authority';
import { CheckIcon, Loader2, X } from 'lucide-react';

import { forwardRef, useMemo } from 'react';
import { cn } from '@/lib/utils';
import { usePreset } from '@/components/ui/labels-context';
import type { IconType } from './types';
import { useStepper } from './use-stepper';

interface StepIconProps {
  isCompletedStep?: boolean;
  isCurrentStep?: boolean;
  isError?: boolean;
  isLoading?: boolean;
  isKeepError?: boolean;
  icon?: IconType;
  index?: number;
  checkIcon?: IconType;
  errorIcon?: IconType;
}

const iconVariants = cva('', {
  variants: {
    size: {
      sm: 'size-4',
      md: 'size-4',
      lg: 'size-5',
    },
  },
  defaultVariants: {
    size: 'md',
  },
});

const figmaIconSizes = { sm: 'h-icon-sm w-icon-sm', md: 'h-icon-sm w-icon-sm', lg: 'h-icon-md w-icon-md' } as const;

const StepIcon = forwardRef<HTMLDivElement, StepIconProps>((props, ref) => {
  const { size, iconSize } = useStepper();
  const zero = usePreset() === 'zero';
  const figma = iconSize === 'figma';
  // Zero: the marker is 22px, so glyphs use the extra small icon and the number the 11/600 label role.
  const iconClass = zero ? 'h-icon-xs w-icon-xs' : figma ? figmaIconSizes[size ?? 'md'] : cn(iconVariants({ size }));

  const {
    isCompletedStep,
    isCurrentStep,
    isError,
    isLoading,
    isKeepError,
    icon: CustomIcon,
    index,
    checkIcon: CustomCheckIcon,
    errorIcon: CustomErrorIcon,
  } = props;

  const Icon = useMemo(() => (CustomIcon ? CustomIcon : null), [CustomIcon]);

  const ErrorIcon = useMemo(() => (CustomErrorIcon ? CustomErrorIcon : null), [CustomErrorIcon]);

  const Check = useMemo(() => (CustomCheckIcon ? CustomCheckIcon : CheckIcon), [CustomCheckIcon]);

  return useMemo(() => {
    if (isCompletedStep) {
      if (isError && isKeepError) {
        return (
          <div key="icon">
            <X className={iconClass} />
          </div>
        );
      }
      return (
        <div key="check-icon">
          <Check className={cn(iconClass, '[stroke-width:var(--size-icon-stroke-check,3)]')} />
        </div>
      );
    }
    if (isCurrentStep) {
      if (isError && ErrorIcon) {
        return (
          <div key="error-icon">
            <ErrorIcon className={iconClass} />
          </div>
        );
      }
      if (isError) {
        return (
          <div key="icon">
            <X className={iconClass} />
          </div>
        );
      }
      if (isLoading) {
        return <Loader2 className={cn(iconClass, 'animate-spin')} />;
      }
    }
    if (Icon) {
      return (
        <div key="step-icon">
          <Icon className={iconClass} />
        </div>
      );
    }
    return (
      <span ref={ref} key="label" className={cn(zero ? 'typography-kpi-label-strong' : figma ? 'typography-ui-medium' : 'text-md', 'text-center font-medium')}>
        {(index || 0) + 1}
      </span>
    );
  }, [isCompletedStep, isCurrentStep, isError, isLoading, Icon, index, Check, ErrorIcon, isKeepError, ref, iconClass, figma, zero]);
});

export { StepIcon };

'use client';

import { cva } from 'class-variance-authority';
import { cn } from '@/lib/utils';
import { usePreset } from '@/components/ui/labels-context';
import { useStepper } from './use-stepper';

interface StepLabelProps {
  isCurrentStep?: boolean;
  // false for a step that is still ahead: the label uses the subtle text role at full opacity
  hasVisited?: boolean;
  label?: string | React.ReactNode;
  description?: string | null;
}

const labelVariants = cva('', {
  variants: {
    size: {
      sm: 'text-sm',
      md: 'text-sm',
      lg: 'text-base',
    },
  },
  defaultVariants: {
    size: 'md',
  },
});

const descriptionVariants = cva('', {
  variants: {
    size: {
      sm: 'text-xs',
      md: 'text-xs',
      lg: 'text-sm',
    },
  },
  defaultVariants: {
    size: 'md',
  },
});

const StepLabel = ({ isCurrentStep, hasVisited = true, label, description }: StepLabelProps) => {
  const { variant, styles, size, orientation } = useStepper();
  const zero = usePreset() === 'zero';
  const shouldRender = !!label || !!description;

  return shouldRender ? (
    <div
      aria-current={isCurrentStep ? 'step' : undefined}
      className={cn(
        'stepper__step-label-container',
        'flex flex-col',
        variant !== 'line' ? 'ms-2' : orientation === 'horizontal' && 'my-2',
        variant === 'circle-alt' && 'text-center',
        variant === 'circle-alt' && orientation === 'horizontal' && 'ms-0',
        variant === 'circle-alt' && orientation === 'vertical' && 'text-start',
        !hasVisited && 'text-text-subtle',
        styles?.['step-label-container'],
      )}
    >
      {!!label && (
        <span className={cn('stepper__step-label', zero ? (isCurrentStep ? 'typography-ui-medium' : 'typography-ui') : labelVariants({ size }), styles?.['step-label'])}>{label}</span>
      )}
      {!!description && (
        <span
          className={cn(
            'stepper__step-description',
            'text-muted-foreground',
            zero ? 'typography-caption' : descriptionVariants({ size }),
            styles?.['step-description'],
          )}
        >
          {description}
        </span>
      )}
    </div>
  ) : null;
};

export { StepLabel };

'use client';

import { forwardRef, Ref } from 'react';
import { HorizontalStep } from './horizontal-step';
import type { StepProps } from './types';
import { useStepper } from './use-stepper';
import { VerticalStep } from './vertical-step';

// Props which shouldn't be passed to to the Step component from the user
interface StepInternalConfig {
  index: number;
  isCompletedStep?: boolean;
  isCurrentStep?: boolean;
  isLastStep?: boolean;
}

interface FullStepProps extends StepProps, StepInternalConfig {}

const Step = forwardRef<HTMLLIElement, StepProps>((props, ref: Ref<any>) => {
  const {
    children,
    description,
    icon,
    state,
    checkIcon,
    errorIcon,
    index,
    isCompletedStep,
    isCurrentStep,
    isLastStep,
    isKeepError,
    label,
    onClickStep,
  } = props as FullStepProps;

  const { isVertical, isError, isLoading, clickable } = useStepper();

  const hasVisited = isCurrentStep || isCompletedStep;

  const sharedProps = {
    isLastStep,
    isCompletedStep,
    isCurrentStep,
    index,
    isError,
    isLoading,
    clickable,
    label,
    description,
    hasVisited,
    icon,
    isKeepError,
    checkIcon,
    state,
    errorIcon,
    onClickStep,
  };

  const renderStep = () => {
    switch (isVertical) {
      case true:
        return (
          <VerticalStep ref={ref} {...sharedProps}>
            {children}
          </VerticalStep>
        );
      default:
        return <HorizontalStep ref={ref} {...sharedProps} />;
    }
  };

  return renderStep();
});

export { Step };

import type { LucideIcon } from 'lucide-react';

type IconType = LucideIcon | React.ComponentType<any> | undefined;

type StepItem = {
  id?: string;
  label?: string;
  description?: string;
  icon?: IconType;
  optional?: boolean;
};

interface StepOptions {
  orientation?: 'vertical' | 'horizontal';
  state?: 'loading' | 'error';
  responsive?: boolean;
  checkIcon?: IconType;
  errorIcon?: IconType;
  onClickStep?: (step: number, setStep: (step: number) => void) => void;
  mobileBreakpoint?: string;
  variant?: 'circle' | 'circle-alt' | 'line';
  expandVerticalSteps?: boolean;
  size?: 'sm' | 'md' | 'lg';
  // Indicator treatment (Figma Progress steps Theme): `light` bare icon, `mid` outlined circle, `dark` filled circle. Omit for the established look.
  theme?: 'light' | 'mid' | 'dark';
  // `figma` sizes icons and step numbers with the icon size tokens and a type role (the default classes `size-4` and `text-md` do not exist in the preset). Omit for the established look.
  iconSize?: 'default' | 'figma';
  styles?: {
    /** Styles for the main container */
    'main-container'?: string;
    /** Styles for the horizontal step */
    'horizontal-step'?: string;
    /** Styles for the horizontal step container (button and labels) */
    'horizontal-step-container'?: string;
    /** Styles for the vertical step */
    'vertical-step'?: string;
    /** Styles for the vertical step container (button and labels) */
    'vertical-step-container'?: string;
    /** Styles for the vertical step content */
    'vertical-step-content'?: string;
    /** Styles for the step button container */
    'step-button-container'?: string;
    /** Styles for the label and description container */
    'step-label-container'?: string;
    /** Styles for the step label */
    'step-label'?: string;
    /** Styles for the step description */
    'step-description'?: string;
  };
  variables?: {
    '--step-icon-size'?: string;
    '--step-gap'?: string;
  };
  scrollTracking?: boolean;
  // Controlled mode: the active step is owned by the parent. Pair with `onStepChange`. Omit for the uncontrolled `initialStep` behaviour.
  activeStep?: number;
  // Called with the next step index whenever the stepper asks to move (nextStep, prevStep, setStep, resetSteps, clicks).
  onStepChange?: (step: number) => void;
}

interface StepperProps extends StepOptions {
  children?: React.ReactNode;
  className?: string;
  initialStep: number;
  steps: StepItem[];
}

interface StepProps extends React.HTMLAttributes<HTMLLIElement> {
  label?: string | React.ReactNode;
  description?: string;
  icon?: IconType;
  state?: 'loading' | 'error';
  checkIcon?: IconType;
  errorIcon?: IconType;
  isCompletedStep?: boolean;
  isKeepError?: boolean;
  onClickStep?: (step: number, setStep: (step: number) => void) => void;
}

interface StepSharedProps extends StepProps {
  isLastStep?: boolean;
  isCurrentStep?: boolean;
  index?: number;
  hasVisited: boolean | undefined;
  isError?: boolean;
  isLoading?: boolean;
}

export type { IconType, StepItem, StepOptions, StepperProps, StepProps, StepSharedProps };

'use client';

import { useEffect, useState } from 'react';

// Works without window.matchMedia (older test DOMs, some embedded webviews): the query then never matches.
export function useMediaQuery(query: string) {
  const [value, setValue] = useState(false);

  useEffect(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return undefined;

    function onChange(event: MediaQueryListEvent) {
      setValue(event.matches);
    }

    const result = window.matchMedia(query);
    setValue(result.matches);
    if (typeof result.addEventListener === 'function') {
      result.addEventListener('change', onChange);
      return () => result.removeEventListener('change', onChange);
    }
    // Safari before 14 only knows the deprecated listener API.
    result.addListener?.(onChange);
    return () => result.removeListener?.(onChange);
  }, [query]);

  return value;
}

'use client';

import { useContext, useEffect, useRef } from 'react';
import { StepperContext } from './context';

function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T>();

  useEffect(() => {
    ref.current = value;
  }, [value]);

  return ref.current;
}

export function useStepper() {
  const context = useContext(StepperContext);

  if (context === undefined) {
    throw new Error('useStepper must be used within a StepperProvider');
  }

  const { children, className, ...rest } = context;

  const isLastStep = context.activeStep === context.steps.length - 1;
  const hasCompletedAllSteps = context.activeStep === context.steps.length;

  const previousActiveStep = usePrevious(context.activeStep);

  const currentStep = context.steps[context.activeStep];
  const isOptionalStep = !!currentStep?.optional;

  const isDisabledStep = context.activeStep === 0;

  return {
    ...rest,
    isLastStep,
    hasCompletedAllSteps,
    isOptionalStep,
    isDisabledStep,
    currentStep,
    previousActiveStep,
  };
}

'use client';

import { cva } from 'class-variance-authority';
import { forwardRef } from 'react';
import { Collapsible, CollapsibleContent } from '@/components/ui/collapsible';
import { cn } from '@/lib/utils';
import { StepButtonContainer } from './step-button-container';
import { StepIcon } from './step-icon';
import { StepLabel } from './step-label';
import type { StepSharedProps } from './types';
import { useStepper } from './use-stepper';

type VerticalStepProps = StepSharedProps & {
  children?: React.ReactNode;
};

const verticalStepVariants = cva(
  [
    'flex flex-col relative transition-all duration-200',
    'data-[completed=true]:[&:not(:last-child)]:after:bg-primary',
    'data-[invalid=true]:[&:not(:last-child)]:after:bg-destructive',
  ],
  {
    variants: {
      variant: {
        circle: cn(
          '[&:not(:last-child)]:pb-[var(--step-gap)] [&:not(:last-child)]:gap-[var(--step-gap)]',
          "[&:not(:last-child)]:after:content-[''] [&:not(:last-child)]:after:w-[2px] [&:not(:last-child)]:after:bg-button-border-outline-default",
          '[&:not(:last-child)]:after:inset-x-[calc(var(--step-icon-size)/2)]',
          '[&:not(:last-child)]:after:absolute',
          '[&:not(:last-child)]:after:top-[calc(var(--step-icon-size)+var(--step-gap))]',
          '[&:not(:last-child)]:after:bottom-[var(--step-gap)]',
          '[&:not(:last-child)]:after:transition-all [&:not(:last-child)]:after:duration-200',
        ),
        line: 'flex-1 border-t-0 mb-4',
      },
    },
  },
);

const VerticalStep = forwardRef<HTMLDivElement, VerticalStepProps>((props, ref) => {
  const {
    children,
    index,
    isCompletedStep,
    isCurrentStep,
    label,
    description,
    icon,
    hasVisited,
    state,
    checkIcon: checkIconProp,
    errorIcon: errorIconProp,
    onClickStep,
  } = props;

  const {
    checkIcon: checkIconContext,
    errorIcon: errorIconContext,
    isError,
    isLoading,
    variant,
    onClickStep: onClickStepGeneral,
    clickable,
    expandVerticalSteps,
    styles,
    scrollTracking,
    orientation,
    steps,
    setStep,
    isLastStep: isLastStepCurrentStep,
    iconSize,
    previousActiveStep,
  } = useStepper();

  const localIsLoading = isLoading || state === 'loading';
  const localIsError = isError || state === 'error';

  const isLastStep = index === steps.length - 1;

  const active = variant === 'line' ? isCompletedStep || isCurrentStep : isCompletedStep;
  const checkIcon = checkIconProp || checkIconContext;
  const errorIcon = errorIconProp || errorIconContext;

  const renderChildren = () => {
    if (!expandVerticalSteps) {
      return (
        <Collapsible open={isCurrentStep}>
          <CollapsibleContent
            ref={(node) => {
              if (
                // If the step is the first step and the previous step
                // was the last step or if the step is not the first step
                // This prevents initial scrolling when the stepper
                // is located anywhere other than the top of the view.
                scrollTracking &&
                ((index === 0 && previousActiveStep && previousActiveStep === steps.length) || (index && index > 0))
              ) {
                node?.scrollIntoView({
                  behavior: 'smooth',
                  block: 'center',
                });
              }
            }}
            className="data-[state=open]:animate-collapsible-down data-[state=closed]:animate-collapsible-up"
          >
            {children}
          </CollapsibleContent>
        </Collapsible>
      );
    }
    return children;
  };

  return (
    <div
      ref={ref}
      className={cn(
        'stepper__vertical-step',
        verticalStepVariants({
          variant: variant?.includes('circle') ? 'circle' : 'line',
        }),
        isLastStepCurrentStep && 'gap-[var(--step-gap)]',
        styles?.['vertical-step'],
      )}
      data-optional={steps[index || 0]?.optional}
      data-completed={isCompletedStep}
      data-active={active}
      data-clickable={clickable || !!onClickStep}
      data-invalid={localIsError}
      onClick={() => onClickStep?.(index || 0, setStep) || onClickStepGeneral?.(index || 0, setStep)}
    >
      <div
        data-vertical={true}
        data-active={active}
        className={cn(
          'stepper__vertical-step-container',
          'flex items-center',
          variant === 'line' && 'border-s-[3px] border-solid py-2 ps-3 data-[active=true]:border-primary',
          styles?.['vertical-step-container'],
        )}
      >
        <StepButtonContainer {...{ isLoading: localIsLoading, isError: localIsError, ...props }}>
          <StepIcon
            {...{
              index,
              isError: localIsError,
              isLoading: localIsLoading,
              isCurrentStep,
              isCompletedStep,
            }}
            icon={icon}
            checkIcon={checkIcon}
            errorIcon={errorIcon}
          />
        </StepButtonContainer>
        <StepLabel label={label} description={description} {...{ isCurrentStep, hasVisited }} />
      </div>
      <div
        className={cn(
          'stepper__vertical-step-content',
          !isLastStep && (iconSize === 'figma' ? 'pb-4' : 'min-h-4'),
          variant !== 'line' && 'ps-[--step-icon-size]',
          variant === 'line' && orientation === 'vertical' && 'min-h-0',
          styles?.['vertical-step-content'],
        )}
      >
        {renderChildren()}
      </div>
    </div>
  );
});

export { VerticalStep };
